css:
.invoice-container { font-family: Arial, sans-serif; font-size: 10pt; color: #000; width: 100%; max-width: 800px; margin: 0 auto; }

/* 1: Membrete + CAI */
.header-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; }
.letterhead-section { flex: 1; }
.cai-block { font-size: 9pt; text-align: left; line-height: 1.4; }

/* 2: Título + No. + Fecha */
.customer-block { font-size: 9pt; text-align: left; line-height: 1.4; }
.invoice-title { font-size: 12pt; text-align: left; }
.invoice-no, .invoice-date { margin: 2px 0; font-size: 10pt; }
.invoice-no{
    font-size:18px;
}

/* 3 y 4: Cliente y RTN */
.customer-info { display: flex; align-items: center; border: 1px solid #000; padding: 4px 8px; margin-bottom: 10px; font-size: 10pt; }
.client-label, .rtn-label { font-weight: bold; margin-right: 8px; }
.client-name { flex: 1; }
.rtn-value { margin-left: auto; }

/* 5: Tabla de Items */
/* Container principal */
.items-container {
    font-size: 9pt;
    margin-bottom: 15px;
}
.items-container.summary {
    border-left:1px solid;
    border-right:1px solid;
    border-bottom:1px solid;
}
.items-container.summary .items-row > div:first-child {
    border-right: 1px solid #000;
}
.items-container.summary .items-row:not(:last-child) {
    border-bottom: 1px solid #000;
}
.items-row.header>div:not(:last-child){
    border-right:1px solid #000;
}
.items-row.body>div:not(:last-child){
    border-right:1px solid #000;
}
/* Fila */
.items-row {
    display: flex;
    margin: 0;
    padding: 0;
}

/* Header */
.items-row.header {
    background: #333;
    color: white;
    font-weight: bold;
    border:1px solid #000 ;
}
.items-row.body {
    border-right: 1px solid #000;
    border-bottom: 1px solid #000;
    border-left: 1px solid #000;
}
.items-row.header > div {
    text-align: center;
    padding: 6px 4px;
}

/* Sistema de 12 columnas (100% / 12 = 8.333% por columna) */
.col-1  { width: 8.333%; }
.col-2  { width: 16.666%; }
.col-3  { width: 25%; }
.col-4  { width: 33.333%; }
.col-5  { width: 41.666%; }
.col-6  { width: 50%; }
.col-7  { width: 58.333%; }
.col-8  { width: 66.666%; }
.col-9  { width: 75%; }
.col-10 { width: 83.333%; }
.col-11 { width: 91.666%; }
.col-12 { width: 100%; }


/* Columnas base */
.items-row > div {
    padding: 6px 4px;
    border-right: 1px solid #ddd;
    box-sizing: border-box;
}
.items-row > div:last-child { border-right: none; }

/* Alineación */
.text-center { text-align: center; }
.text-right { text-align: right; }

/* Cantidad en letra */
.in-words-col {
    padding: 6px 8px;
    font-size: 8.5pt;
}
.in-words strong { font-weight: bold; }

/* Total a Pagar */

/* Total General */
.grand-total-box { text-align: right; margin-bottom: 15px; }
.grand-total-box span:first-child { display: inline-block; border: 1px solid #000; padding: 4px 12px; font-weight: bold; }
.grand-total-value { display: inline-block; border: 1px solid #000; padding: 4px 20px; font-size: 11pt; font-weight: bold; margin-left: 10px; }

/* 6 y 7: Footer */
.footer-section { display: flex; justify-content: space-between; font-size: 9pt; margin-top: 10px; }
.left-column { width: 55%; }
.exijala { font-weight: bold; padding: 0 0 5px 0; text-align: left; }
.exempt-block { font-size: 9pt; text-align: left; line-height: 1.2; }
.copies { padding-top: 10px; text-align: left; font-weight: bold;font-size:8pt; }

.right-column { width: 40%;font-size:10px; }
.tax-table { width: 100%; border: 1px solid #000; border-collapse: collapse; }
.tax-table td { border: 1px solid #000;  }
.tax-table .text-right { text-align: right; }
.total-pagar td { background: #ddd; font-weight: bold; }

/* Valor en Letras */
.in-words { margin-top: 15px; font-size: 9pt;  solid #000; padding-top: 5px; }
